/**
 * Pure commission calculation function — no side effects, no imports.
 * Used in CommissionPreview, RuleEditorDrawer, and NewBookingDrawer.
 *
 * All amounts are in cents.
 */

export interface CommissionPreviewRule {
  percentage: number | null
  flat_fee_cents: number | null
  tip_split_pct: number
}

export interface CommissionPreviewResult {
  commission: number
  tipCommission: number
  total: number
  breakdown: string
}

/**
 * Calculate artist commission from service price, tip, and rule.
 * Mirrors the trigger logic in `on_booking_completed_commission`.
 *
 * @param price            Service price in cents.
 * @param tip              Tip amount in cents.
 * @param rule             Resolved commission rule (percentage, flat_fee_cents, tip_split_pct).
 *                         May be null/undefined when no rule matched and no artist default exists.
 * @param artistDefaultPct Optional fallback percentage from `artists.commission_default_pct`.
 *                         Used when no rule matches — mirrors the trigger's artist_default path.
 *                         Pass `null` or omit to skip the fallback (returns $0 commission).
 */
export function calculateCommission(
  price: number,
  tip: number,
  rule: CommissionPreviewRule | null | undefined,
  artistDefaultPct: number | null = null,
): CommissionPreviewResult {
  // If no rule supplied, fall back to artist default pct (mirrors trigger behaviour)
  const effectiveRule: CommissionPreviewRule =
    rule ?? (artistDefaultPct != null
      ? { percentage: artistDefaultPct, flat_fee_cents: null, tip_split_pct: 100 }
      : { percentage: null, flat_fee_cents: null, tip_split_pct: 100 })

  let commission = 0
  const parts: string[] = []

  if (effectiveRule.percentage != null && effectiveRule.flat_fee_cents != null) {
    commission =
      Math.round((price * effectiveRule.percentage) / 100) + effectiveRule.flat_fee_cents
    parts.push(`${effectiveRule.percentage}% + flat fee`)
  } else if (effectiveRule.percentage != null) {
    commission = Math.round((price * effectiveRule.percentage) / 100)
    parts.push(`${effectiveRule.percentage}%`)
  } else if (effectiveRule.flat_fee_cents != null) {
    commission = effectiveRule.flat_fee_cents
    parts.push(`flat fee`)
  }

  const tipCommission = Math.round((tip * effectiveRule.tip_split_pct) / 100)
  if (tip > 0 && effectiveRule.tip_split_pct > 0) {
    parts.push(`${effectiveRule.tip_split_pct}% tip`)
  }

  return {
    commission,
    tipCommission,
    total: commission + tipCommission,
    breakdown: parts.join(' + '),
  }
}

