// Derived preview rule
// Use explicit Number.isFinite check so that entering "0" does not become null
// (parseFloat("0") || null converts 0% to null — silent data loss on flat-fee-only rules)
const parsePct = (s: string): number | null => {
  const n = parseFloat(s)
  return Number.isFinite(n) ? n : null
}
const parseCents = (s: string): number | null => {
  const n = parseFloat(s)
  const cents = Number.isFinite(n) ? Math.round(n * 100) : null
  return cents === 0 ? null : cents
}

