'use client'

import { useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { formatCurrency } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const ALLOWED_TRANSITIONS: Record<BookingStatus, BookingStatus[]> = {
  pending:     ['confirmed', 'cancelled'],
  confirmed:   ['in_progress', 'cancelled', 'no_show'],
  in_progress: ['completed', 'cancelled'],
  completed:   [],
  cancelled:   [],
  no_show:     [],
}

const TRANSITION_LABELS: Record<BookingStatus, string> = {
  confirmed:   'Confirm',
  in_progress: 'Start session',
  completed:   'Mark complete',
  cancelled:   'Cancel',
  no_show:     'No show',
  pending:     'Revert to pending',
}

const TRANSITION_VARIANT: Record<BookingStatus, 'default' | 'outline' | 'destructive'> = {
  confirmed:   'default',
  in_progress: 'default',
  completed:   'default',
  cancelled:   'destructive',
  no_show:     'outline',
  pending:     'outline',
}

/** Statuses that trigger a penalty adjustment via DB trigger on cancellation */
const PENALTY_TRIGGER_STATUSES: BookingStatus[] = ['cancelled', 'no_show']

interface CommissionRecord {
  status: string
  total_cents: number
}

interface StatusTransitionButtonsProps {
  bookingId: string
  currentStatus: BookingStatus
}

export function StatusTransitionButtons({
  bookingId,
  currentStatus,
}: StatusTransitionButtonsProps) {
  const queryClient = useQueryClient()
  const targets = ALLOWED_TRANSITIONS[currentStatus]

  /** Target status pending user confirmation — null = no dialog open */
  const [pendingTarget, setPendingTarget] = useState<BookingStatus | null>(null)

  // Fetch commission record so cancel dialog can warn about approved commissions.
  // Only enabled when the booking is in a state that CAN transition to cancelled/no_show
  // AND when there are such targets available.
  const hasCancelTarget = targets.some((t) => PENALTY_TRIGGER_STATUSES.includes(t))
  const { data: commissionData } = useQuery<{ data: CommissionRecord | null }>({
    queryKey: ['booking-commission', bookingId],
    queryFn: () => fetch(`/api/bookings/${bookingId}/commission`).then((r) => r.json()),
    staleTime: 30_000,
    enabled: hasCancelTarget,
  })

  const commission = commissionData?.data
  const hasApprovedCommission =
    commission != null && ['approved', 'paid'].includes(commission.status)

  const mutation = useMutation({
    mutationFn: async (newStatus: BookingStatus) => {
      const res = await fetch(`/api/bookings/${bookingId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to update status')
      }
    },
    onSuccess: (_data, newStatus) => {
      void queryClient.invalidateQueries({ queryKey: ['booking', bookingId] })
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      void queryClient.invalidateQueries({ queryKey: ['booking-commission', bookingId] })
      toast.success(`Status updated to ${newStatus.replace('_', ' ')}`)
      logger.info({ bookingId, newStatus }, 'booking status updated')
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err, bookingId }, 'status transition failed')
    },
  })

  function handleClick(target: BookingStatus) {
    // Show confirmation dialog for cancel/no_show when an approved commission exists
    if (PENALTY_TRIGGER_STATUSES.includes(target) && hasApprovedCommission) {
      setPendingTarget(target)
      return
    }
    mutation.mutate(target)
  }

  function handleConfirmCancel() {
    if (pendingTarget) mutation.mutate(pendingTarget)
    setPendingTarget(null)
  }

  if (targets.length === 0) {
    return (
      <p className="text-xs text-muted-foreground">
        No further transitions available.
      </p>
    )
  }

  return (
    <>
      <div className="flex flex-wrap gap-2">
        {targets.map((target) => (
          <Button
            key={target}
            variant={TRANSITION_VARIANT[target]}
            size="sm"
            className="h-8 text-xs"
            disabled={mutation.isPending}
            onClick={() => handleClick(target)}
          >
            {mutation.isPending && mutation.variables === target
              ? 'Updating...'
              : TRANSITION_LABELS[target]}
          </Button>
        ))}
      </div>

      {/* Commission penalty warning dialog — shown when cancelling a booking
          that has an approved or paid commission (DB trigger auto-creates penalty) */}
      <AlertDialog
        open={pendingTarget !== null}
        onOpenChange={(open) => { if (!open) setPendingTarget(null) }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Commission penalty will be created</AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-2 text-sm text-muted-foreground">
                <p>
                  This booking has an approved commission of{' '}
                  <span className="font-semibold text-foreground">
                    {commission ? formatCurrency(commission.total_cents) : '—'}
                  </span>{' '}
                  that was already recorded.
                </p>
                <p>
                  Cancelling will automatically create a pending penalty adjustment
                  that must be resolved in the Commissions tab.
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Never mind</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmCancel}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Continue &amp; cancel booking
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

