// Use atomic version-swap RPC: expires old rule + inserts new version in one transaction.
// Direct UPDATE is intentionally avoided — commission rules are legal pay records.
//
// The `update_commission_rule` RPC was added in migration 20260416000005.
// Until `pnpm db:types` is run post-migration, it is absent from the generated
// Database type. We cast through `unknown` here — this is safe and deliberate;
// the cast is removed once types are regenerated. Zero loss of runtime type safety
// since the RPC signature is defined in the migration above.
const rpcCall = supabase.rpc as unknown as (
  fn: string,
  args: Record<string, unknown>,
) => PromiseLike<UpdateCommissionRuleResult>

const { data: newRuleId, error } = await rpcCall('update_commission_rule', {
  p_rule_id:         id,
  p_percentage:      body.data.percentage ?? null,
  p_flat_fee_cents:  body.data.flat_fee_cents ?? null,
  p_tip_split_pct:   body.data.tip_split_pct ?? null,
  p_priority:        body.data.priority ?? null,
  p_effective_until: body.data.effective_until ?? null,
})
